  \node at (1,0.55) {$(x_P,y_P)$};
  \draw[blue,->] (1,1) -- (1,2) node[right] {$\vec Z$};
  \draw[red,->]  (2.2,1) -- (2.2,2) node[right] {$\vec a$};
